def isValidTriangle(a, b, c):
    if a + b > c and a + c > b and b + c > a:
        return 1
    return 0

def main():
    a, b, c = map(int, input().split())
    result = isValidTriangle(a, b, c)
    if result == 1:
        print("Valid")
    else:
        print("Not Valid")

if __name__ == "__main__":
    main()
